"""Wireshark configuration profiles: listing, reading (to import) and using one (-C)."""

from __future__ import annotations

from pathlib import Path

import pytest

from pcap_backend import coloring, index_cache, tshark, wsprofile
from pcap_backend.pcap_service import PcapService
from pcap_backend.protocol import InvalidParamsError, RequestContext
from pcap_backend.tshark import ConfigError, DissectionOptions

FIXTURES = Path(__file__).resolve().parents[1] / "fixtures"

COLORFILTERS = (
    "# DO NOT EDIT THIS FILE!  It was created by Wireshark\n"
    "@Bad TCP@tcp.analysis.flags && !tcp.analysis.window_update@[0,0,0][65535,24383,24383]\n"
    "!@HTTP@http || tcp.port == 80@[0,0,0][58596,65535,51143]\n"
    "not a rule\n"
)
BUTTONS = (
    "# This file is automatically generated, DO NOT MODIFY.\n"
    '"TRUE","Web","http || tls","Web traffic"\n'
    '"FALSE","Quoted","http.host == \\x22example.com\\x22",""\n'
    '"TRUE","","no label",""\n'
)
DFILTERS = '"No ARP" not arp\n# a comment\n"Web" http\n"bad line\n'
MACROS = '"web","tcp.port == $1"\n"private","ip.addr == 10.0.0.0/8"\n'
PREFERENCES = (
    "# Packet list column format\n"
    "gui.column.format:\n"
    '\t"No.", "%m",\n'
    '\t"Time", "%Yt",\n'
    '\t"Delta", "%Gt",\n'
    '\t"Source", "%s",\n'
    '\t"TTL", "%Cus:ip.ttl:0:R",\n'
    '\t"Address", "%Cus:ip.src or ipv6.src:0:R",\n'
    '\t"Info", "%i"\n'
    "\n"
    "#tcp.check_checksum: FALSE\n"
    "tcp.analyze_sequence_numbers: FALSE\n"
)


def test_parse_profile_files() -> None:
    assert wsprofile.parse_colorfilters(COLORFILTERS) == [
        {
            "name": "Bad TCP",
            "filter": "tcp.analysis.flags && !tcp.analysis.window_update",
            "foreground": "#000000",
            "background": "#ff5f5f",
            "enabled": True,
        },
        {
            "name": "HTTP",
            "filter": "http || tcp.port == 80",
            "foreground": "#000000",
            "background": "#e4ffc7",
            "enabled": False,
        },
    ]
    assert wsprofile.parse_filter_buttons(BUTTONS) == [
        {"label": "Web", "filter": "http || tls", "comment": "Web traffic", "enabled": True},
        {
            "label": "Quoted",
            "filter": 'http.host == "example.com"',
            "comment": "",
            "enabled": False,
        },
    ]
    assert wsprofile.parse_dfilters(DFILTERS) == [
        {"name": "No ARP", "filter": "not arp"},
        {"name": "Web", "filter": "http"},
    ]
    assert [m["name"] for m in wsprofile.parse_macros(MACROS)] == ["web", "private"]
    # Every time format is the Time column (once); a custom column of several
    # fields can't be one of PCAP Lens's.
    assert wsprofile.parse_columns(PREFERENCES) == [
        {"title": "No.", "id": "number"},
        {"title": "Time", "id": "time"},
        {"title": "Source", "id": "source"},
        {"title": "TTL", "field": "ip.ttl"},
        {"title": "Info", "id": "info"},
    ]
    assert wsprofile.preference(PREFERENCES, "tcp.check_checksum") is None, "commented out"
    assert wsprofile.preference(PREFERENCES, "tcp.analyze_sequence_numbers") == "FALSE"


def test_uat_fields() -> None:
    assert wsprofile.uat_fields('"a","b \\x2c c", "\\\\d"') == ["a", "b , c", "\\d"]
    assert wsprofile.uat_fields("# comment") is None
    assert wsprofile.uat_fields('"a",b') is None
    assert wsprofile.uat_fields("") is None


def test_list_profiles(tmp_path: Path) -> None:
    personal, global_ = tmp_path / "personal", tmp_path / "global"
    (personal / "profiles" / "Mine").mkdir(parents=True)
    (personal / "profiles" / "Mine" / "colorfilters").write_text(COLORFILTERS)
    (personal / "profiles" / "Bluetooth").mkdir()
    (global_ / "profiles" / "Bluetooth").mkdir(parents=True)
    (global_ / "profiles" / "Classic").mkdir()
    (personal / "preferences").write_text(PREFERENCES)
    listed = wsprofile.list_profiles(personal, global_)
    assert [(p["name"], p["global"], p["default"]) for p in listed] == [
        ("Default", False, True),
        ("Bluetooth", False, False),  # the personal copy hides the global one
        ("Mine", False, False),
        ("Classic", True, False),
    ]
    assert listed[0]["files"] == ["preferences"]
    assert listed[2]["files"] == ["colorfilters"]
    assert wsprofile.profile_dir(personal, global_, "Classic") == global_ / "profiles" / "Classic"
    assert wsprofile.profile_dir(personal, global_, "Nope") is None
    assert wsprofile.valid_name("No Reassembly")
    assert not any(wsprofile.valid_name(n) for n in ("", "..", "a/b", " x", "a\nb"))


def test_coloring_config_goes_into_the_profile(tmp_path: Path) -> None:
    personal, profile, target = tmp_path / "p", tmp_path / "prof", tmp_path / "t"
    for d in (personal, profile, target):
        d.mkdir()
    (personal / "preferences").write_text("a: 1\n")
    (profile / "preferences").write_text("b: 2\n")
    (profile / "colorfilters").write_text("@old@x@[0,0,0][0,0,0]\n")
    coloring.prepare_config_dir(
        target, [coloring.ColorRule("tcp", "#000000", "#ffffff")], personal, ("Mine", profile)
    )
    assert (target / "preferences").read_text() == "a: 1\n"
    assert (target / "profiles" / "Mine" / "preferences").read_text() == "b: 2\n"
    assert "@0@tcp@" in (target / "profiles" / "Mine" / "colorfilters").read_text()
    assert not (target / "colorfilters").exists()


def test_profile_options() -> None:
    options = DissectionOptions.from_params(profile="No Reassembly")
    assert options.args()[:2] == ["-C", "No Reassembly"]
    assert "-C" not in options.args(profile=False)
    with pytest.raises(ConfigError):
        DissectionOptions.from_params(profile="../etc")
    key = {
        "capture": FIXTURES / "http.pcap",
        "tshark": Path("/usr/bin/tshark"),
        "tshark_version": "4.2",
        "lua_scripts": [],
        "decode_as": [],
        "prefs": {},
        "columns": [],
        "config": [],
    }
    assert index_cache.index_key(**key) != index_cache.index_key(**key, profile="Mine")


@pytest.fixture
def personal(
    service: PcapService, ctx: RequestContext, tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> Path:
    """An empty personal configuration folder (a temporary home), as tshark finds it."""
    for var in ("HOME", "APPDATA", "XDG_CONFIG_HOME"):
        monkeypatch.setenv(var, str(tmp_path / "home"))
    monkeypatch.setattr(tshark, "_FOLDERS", {})  # folders are cached per tshark
    service.initialize({}, ctx)
    folder = Path(service.wireshark_profiles({}, ctx)["profiles"][0]["path"])
    folder.mkdir(parents=True, exist_ok=True)
    return folder


@pytest.mark.tshark
def test_a_profile_is_listed_read_and_used(
    service: PcapService, ctx: RequestContext, personal: Path
) -> None:
    mine = personal / "profiles" / "PV Test"
    mine.mkdir(parents=True)
    (mine / "colorfilters").write_text(COLORFILTERS)
    (mine / "dfilter_buttons").write_text(BUTTONS)
    (mine / "dfilters").write_text(DFILTERS)
    (mine / "dfilter_macros").write_text(MACROS)
    (mine / "preferences").write_text(PREFERENCES)
    listed = service.wireshark_profiles({}, ctx)["profiles"]
    assert listed[0]["name"] == "Default"
    entry = next(p for p in listed if p["name"] == "PV Test")
    assert entry["files"] == [
        "preferences",
        "colorfilters",
        "dfilter_buttons",
        "dfilters",
        "dfilter_macros",
    ]
    read = service.read_wireshark_profile({"name": "PV Test"}, ctx)
    assert [r["name"] for r in read["coloringRules"]] == ["Bad TCP", "HTTP"]
    assert [b["label"] for b in read["filterButtons"]] == ["Web", "Quoted"]
    assert read["columns"][3] == {"title": "TTL", "field": "ip.ttl"}
    assert (read["preferences"], len(read["macros"])) == (2, 2)
    assert service.read_wireshark_profile({}, ctx)["name"] == "Default"
    with pytest.raises(InvalidParamsError, match="does not exist"):
        service.read_wireshark_profile({"name": "Nope"}, ctx)

    # Used: tshark expands the profile's macros, and coloring passes still work.
    service.open({"path": str(FIXTURES / "http.pcap"), "profile": "PV Test"}, ctx)
    res = service.set_filter({"expr": "${web:80} && http"}, ctx)
    assert res["matchCount"] == 2
    colors = service.set_coloring({"rules": [{"filter": "http", "background": "#ddeeff"}]}, ctx)
    assert colors["colored"] == 2
    with pytest.raises(ConfigError, match="does not exist"):
        service.open({"path": str(FIXTURES / "http.pcap"), "profile": "Nope"}, ctx)
